  const v=Math.max(0,Math.min(1,blend*0.5+0.5));
  const pal=[[2,3,15],[4,12,38],[8,35,65],[0,140,160],[0,255,190],[200,255,80],[255,100,220],[255,50,50],[140,15,90],[30,4,22]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.65+Math.abs(reaction)*0.55;
  const edge=Math.abs(reaction)>0.55?1.5:1.0;
  const neon=Math.max(0,reaction-0.25)*0.9;
  const uiBoost=(bar+spark+corner+numGlow)*0.6;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+neon*60+uiBoost*40)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+neon*110+uiBoost*80)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+neon*90+uiBoost*70)|0
  ];
}
